static const char *ITER_KEY = "3A3B39B5C3F2376D69F7D546E5F85D43", *ITER_IN = "CA49C1C75771AB0B", *ITER_OUT = "738BAD4C4A690802";

static int hexbytes(const char *s, u8 *out) {
    int n = 0;
    for (; s[0] && s[1]; s += 2) {
        int v = 0;
        for (int i = 0; i < 2; i++) { char c = s[i]; v = v * 16 + (c <= '9' ? c - '0' : c >= 'a' ? c - 'a' + 10 : c - 'A' + 10); }
        out[n++] = (u8)v;
    }
    return n;
}

// ---- KASUMI (3GPP TS 35.202) ----
#ifndef KAS_CFLIP
#define KAS_CFLIP 0            // XORed into the key-schedule constants (negative control only)
#endif
static u16 rol16(u16 x, int n) { return (u16)((x << n) | (x >> (16 - n))); }
static u16 KLs[8][2], KOs[8][3], KIs[8][3];
static struct kset G;                                   // everything the run computes, in the layout of the published data
static void kasumi_key(const u8 *key) {
    u16 K[8], Kp[8];
    for (int j = 0; j < 8; j++) { K[j] = (u16)((key[2 * j] << 8) | key[2 * j + 1]); Kp[j] = (u16)(K[j] ^ CT[j] ^ KAS_CFLIP); }
    for (int r = 0; r < 8; r++) {
        KLs[r][0] = rol16(K[r], 1);              KLs[r][1] = Kp[(r + 2) & 7];
        KOs[r][0] = rol16(K[(r + 1) & 7], 5);    KOs[r][1] = rol16(K[(r + 5) & 7], 8);    KOs[r][2] = rol16(K[(r + 6) & 7], 13);
        KIs[r][0] = Kp[(r + 4) & 7];             KIs[r][1] = Kp[(r + 3) & 7];             KIs[r][2] = Kp[(r + 7) & 7];
        G.sk[0][r] = KLs[r][0]; G.sk[1][r] = KLs[r][1];
        G.sk[2][r] = KOs[r][0]; G.sk[3][r] = KOs[r][1]; G.sk[4][r] = KOs[r][2];
        G.sk[5][r] = KIs[r][0]; G.sk[6][r] = KIs[r][1]; G.sk[7][r] = KIs[r][2];
    }
}
static u16 FI(u16 in, u16 ki, int r, int j) {            // r = 0..7, j = 0..2
    u16 l0 = in >> 7, r0 = in & 0x7f, ki1 = ki >> 9, ki2 = ki & 0x1ff;
    u16 s9a = S9T[l0];                                   // S9[L0]
    u16 r1 = s9a ^ r0;                                   // R1 = S9[L0] ^ ZE(R0)
    u16 l2 = r1 ^ ki2;
    u16 s7a = S7T[r0];
    u16 r2 = (u16)(s7a ^ (r1 & 0x7f) ^ ki1);             // R2 = S7[L1] ^ TR(R1) ^ KI1, L1 = R0
    u16 s9b = S9T[l2];
    u16 r3 = s9b ^ r2;                                   // R3 = S9[L2] ^ ZE(R2)
    u16 s7b = S7T[r2];
    u16 l4 = (u16)(s7b ^ (r3 & 0x7f));                   // L4 = S7[L3] ^ TR(R3), L3 = R2
    u16 out = (u16)((l4 << 9) | r3);
    u8 *sv = G.sv[r][j]; u16 *nn = G.nn[r][j];
    sv[0] = (u8)r0; sv[1] = (u8)s7a; sv[2] = (u8)(s7a ^ (r1 & 0x7f)); sv[3] = (u8)r2; sv[4] = (u8)s7b; sv[5] = (u8)l4;
    nn[0] = l0; nn[1] = s9a; nn[2] = r1; nn[3] = l2; nn[4] = s9b; nn[5] = r3;
    G.fi[r][j][0] = in; G.fi[r][j][1] = ki; G.fi[r][j][2] = out;
    return out;
}
static u32 FO(u32 in, int r) {
    u16 l = (u16)(in >> 16), rr = (u16)in;
    for (int j = 0; j < 3; j++) { u16 t = FI(l ^ KOs[r][j], KIs[r][j], r, j) ^ rr; l = rr; rr = t; }   // Rj = FI(Lj-1 ^ KOj, KIj) ^ Rj-1, Lj = Rj-1
    u32 out = ((u32)l << 16) | rr;
    G.fo[r][0] = in; G.fo[r][1] = out;
    return out;
}
static u32 FL(u32 in, int r) {
    u16 l = (u16)(in >> 16), rr = (u16)in;
    rr ^= rol16(l & KLs[r][0], 1); l ^= rol16(rr | KLs[r][1], 1);
    u32 out = ((u32)l << 16) | rr;
    G.fl[r][0] = in; G.fl[r][1] = KLs[r][0]; G.fl[r][2] = KLs[r][1]; G.fl[r][3] = out;
    return out;
}
static u32 be32(const u8 *p) { return ((u32)p[0] << 24) | ((u32)p[1] << 16) | ((u32)p[2] << 8) | p[3]; }
static void put32(u8 *p, u32 v) { p[0] = (u8)(v >> 24); p[1] = (u8)(v >> 16); p[2] = (u8)(v >> 8); p[3] = (u8)v; }
static void kasumi_enc(const u8 *in, u8 *out) {
    u32 L = be32(in), R = be32(in + 4);
    for (int i = 1; i <= 8; i++) {
        u32 f = (i & 1) ? FO(FL(L, i - 1), i - 1) : FL(FO(L, i - 1), i - 1);   // odd rounds FL then FO, even rounds FO then FL
        u32 nl = R ^ f; R = L; L = nl;
    }
    put32(out, L); put32(out + 4, R);
}

static int total, bad;
static void cmp(u32 got, u32 want, int set, const char *what, int r) {
    total++;
    if (got != want) { bad++; if (bad <= 8) { pstr("FAIL set "); pdec(set); pstr(" "); pstr(what); pstr(" index "); pdec(r); pstr(": "); phex(got, 8); pstr(" expected "); phex(want, 8); pstr("\n"); } }
}
int paper_main(void) {
    // the two worked examples of the specification
    cmp(S7T[38], 58, 0, "S7[38]", 0); cmp(S9T[138], 339, 0, "S9[138]", 0);
    for (int s = 0; s < 3; s++) {
        const struct kset *E = &KSETS[s];
        u8 key[16], in[8], out[8], want[8];
        hexbytes(E->key, key); hexbytes(E->in, in); hexbytes(E->out, want);
        int t0 = total, b0 = bad;
        kasumi_key(key); kasumi_enc(in, out);
        for (int a = 0; a < 8; a++) for (int r = 0; r < 8; r++) cmp(G.sk[a][r], E->sk[a][r], s + 1, "subkey", a * 8 + r);
        for (int r = 0; r < 8; r++) {
            for (int k = 0; k < 4; k++) cmp(G.fl[r][k], E->fl[r][k], s + 1, "FL", r * 4 + k);
            for (int k = 0; k < 2; k++) cmp(G.fo[r][k], E->fo[r][k], s + 1, "FO", r * 2 + k);
            for (int j = 0; j < 3; j++) {
                for (int k = 0; k < 3; k++) cmp(G.fi[r][j][k], E->fi[r][j][k], s + 1, "FI", (r * 3 + j) * 3 + k);
                for (int k = 0; k < 6; k++) { cmp(G.sv[r][j][k], E->sv[r][j][k], s + 1, "FI 7-bit path", (r * 3 + j) * 6 + k); cmp(G.nn[r][j][k], E->nn[r][j][k], s + 1, "FI 9-bit path", (r * 3 + j) * 6 + k); }
            }
        }
        cmp(be32(out), be32(want), s + 1, "output high", 0); cmp(be32(out + 4), be32(want + 4), s + 1, "output low", 0);
        pstr("TS 35.203 test set "); pdec(s + 1); pstr(": output "); phex_bytes(out, 8); pstr(", "); pdec(total - t0); pstr(" published values compared, "); pdec(bad - b0); pstr(" mismatches\n");
    }
    {   // test set 4: 50 chained encryptions
        u8 key[16], blk[8], want[8];
        hexbytes(ITER_KEY, key); hexbytes(ITER_IN, blk); hexbytes(ITER_OUT, want);
        kasumi_key(key);
        for (int i = 0; i < 50; i++) { u8 o[8]; kasumi_enc(blk, o); for (int j = 0; j < 8; j++) blk[j] = o[j]; }
        int ok = pcheck_bytes("test set 4, 50 chained encryptions", blk, want, 8);
        total++; if (!ok) bad++;
    }
    pstr("published values compared: "); pdec(total); pstr(", mismatches "); pdec(bad); pstr("\n");
    pstr(bad ? "FAIL\n" : "PASS\n");
    return bad ? 1 : 0;
}
